message.content:
{ 
"description": "The creature is a single quadrupedal hybrid shown in right-facing profile, with the overall size, posture, fur, head and limbs of a brown bear combined with insect-like structures on its back and forehead. It is covered in dense, shaggy brown fur that is darker brown on the lower legs and back and lighter tan on the muzzle, cheeks and flanks, standing on four sturdy legs with a very short tail at the rear. A large, glossy, dark reddish-brown segmented shell covers the entire dorsal surface from just behind the shoulders to the rump, and a single long, curved, dark horn with jagged notches projects upward from the forehead. The head is bear-like with a long snout and black nose, small rounded ears, and brown eyes, and a row of oval openings is visible on the fur of the flank just below the lower edge of the shell.",
"parts": [
  {
    "part": "head",
    "looks_like": "bear-like head with elongated tan-brown muzzle, large black nose with nostrils, small brown eyes, and lighter fur around the mouth and cheeks",
    "where": "at the front of the body, attached to the thick furry neck"
  },
  {
    "part": "horns",
    "looks_like": "one large glossy dark brown to black curved horn with a sharp tip, a small forward-pointing prong near the tip, and several rounded notches and serrations along the inner curve, with a tiny secondary point at the base",
    "where": "rising from the midline of the forehead between the ears, curving upward and slightly backward"
  },
  {
    "part": "ears",
    "looks_like": "two small rounded furry ears covered in brown fur, with slightly darker edges",
    "where": "on top of the head, one on each side of the base of the horn"
  },
  {
    "part": "legs",
    "looks_like": "four thick, heavily furred legs with long shaggy brown fur, muscular in shape, two forelegs under the chest and two hind legs under the hips",
    "where": "supporting the body from below, forelegs at the front and hind legs at the rear"
  },
  {
    "part": "feet",
    "looks_like": "four broad paws with dark curved claws, the fur extends over the top of the paws and the claws protrude from the front edge, five claws visible on each front paw and hind paw",
    "where": "at the bottom ends of each leg, in contact with the ground"
  },
  {
    "part": "tail",
    "looks_like": "very short, small rounded tuft of brown fur, barely protruding from the fur of the rump",
    "where": "at the extreme rear of the body, below the back edge of the shell"
  },
  {
    "part": "shell",
    "looks_like": "large domed glossy shell in dark reddish-brown to black, smooth and reflective, covering the back like a beetle elytra",
    "where": "on the dorsal side, extending from behind the shoulders over the entire back to the rump, sitting on top of the fur"
  },
  {
    "part": "plates",
    "looks_like": "overlapping transverse segmented plates forming the shell, with about 10-12 ridged segments along the mid-back and a larger smooth shoulder shield at the front with horizontal striations and small circular pits along its lower margin, plus a row of small rectangular plates with paired oval pits along the lower edge of the main shell",
    "where": "composing the shell on the back, the large shield over the shoulders and the segmented bands behind it"
  },
  {
    "part": "markings",
    "looks_like": "a horizontal row of seven oval dark-rimmed openings with light centers, resembling spiracles, each surrounded by brown fur",
    "where": "on the side of the torso on the fur, just below the lower edge of the shell plates, running along the flank from mid-body toward the hind leg"
  }
],
"attached_objects": [],
"animals": ["bear", "rhinoceros beetle"],
"separate_bodies": 1,
"heads": 1,
"walking_legs": 4,
"wings": 0,
"extra_limb_pieces": 0
}
